def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """

    if isinstance(nanoseconds, (int, float)):
        nanoseconds = int(nanoseconds)
    else:
        raise ValueError("`nanoseconds` must be an integer or a float value.")

    if not tz or tz == "None":
        tz = None

    try:
        time_obj = datetime.datetime.fromtimestamp(nanoseconds/1e9, tz=tz)
    except ValueError:
        raise ValueError("Invalid input time value.")

    return Time(time_obj)
