def unit_of_work(tx_func, metadata=None, timeout=None):
    def inner():
        if timeout is not None:
            # Set the transaction timeout if specified
            tx._timeout = timeout

        if metadata is not None:
            # Set the transaction metadata if specified
            tx._metadata = metadata

        try:
            # Execute the transaction function
            res = tx_func(tx)
        except Exception as e:
            # Rollback the transaction if an exception was thrown
            tx.rollback()
            raise e
        else:
            # Commit the transaction if no exception was thrown
            tx.commit()
            return res

    # return the inner wrapper function
    return inner

