    parts = s.split(".")
    ints = []
    for part in parts:
        try:
            ints.append(int(part))
        except ValueError:
            pass
    if len(ints) > 3:
        raise ValueError("Too many version numbers specified: {}".format(s))
    while len(ints) < 3:
        ints.append(0)
    return tuple(ints)

