def _extract_number_and_supplment_from_issue_element(issue):
    match = re.search(r"<issue>(.*?)</issue>", issue)
    if match:
        issue_text = match.group(1).strip()
    else:
        raise ValueError("Invalid issue element")

    # extract the number
    match = re.search(r"\d+", issue_text)
    if match:
        number = match.group(0)
    else:
        raise ValueError("No number found in issue element")

    # extract the supplement
    match = re.search(r"suppl|suppl\s*\d*", issue_text, re.I)
    if match:
        supplement = match.group(0)
    else:
        supplement = None

    return number, supplement

