def absorb(self, args: List[str]):
        """
        Given an `args` sequence of expressions, return a new list of expressions
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """

        # Check if args list is valid
        if not args:
            raise ValueError("Invalid argument(s): 'args' cannot be empty.")

        for expr in args:
            if not isinstance(expr, str):
                raise ValueError(f"Invalid argument: 'expr' must be a string, but got {type(expr).__name__}.")

        absorbed_exprs = []
        for expr in args:
            if "|" in expr and "&" in expr:
                raise ValueError(f"Invalid argument: 'expr' cannot contain both '|' and '&' operators. Got {expr}.")
            elif "|" in expr:
                # Handle absorption
                expr_parts = expr.split("|")
                if len(expr_parts) != 2:
                    raise ValueError(f"Invalid argument: 'expr' should have only one '|' operator. Got {expr}.")
                lhs, rhs = expr_parts
                if lhs == rhs:
                    absorbed_exprs.append(lhs)
            elif "&" in expr:
                # Handle negative absorption
                expr_parts = expr.split("&")
                if len(expr_parts) != 2:
                    raise ValueError(f"Invalid argument: 'expr' should have only one '&' operator. Got {expr}.")
                lhs, rhs = expr_parts
                if lhs == ~rhs:
                    absorbed_exprs.append(lhs & rhs)
        return sorted(absorbed_exprs)

