def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    from subprocess import check_output, check_call, CalledProcessError

    # If the commands is a list, join it into a single command string
    if isinstance(commands, list):
        commands = " ".join(commands)

    # If the arguments are a list, join it into a single string
    if isinstance(args, list):
        args = " ".join(args)

    # Create the call string
    call = [commands, args]

    # If a working directory is specified, change to it
    if cwd:
        os.chdir(cwd)

    # If the verbose flag is set, echo the command being called
    if verbose:
        print(f"Calling command: {call}")

    # If the hide_stderr flag is set, do not capture stderr
    if hide_stderr:
        output = check_output(call, shell=True)
    else:
        output = check_call(call, shell=True)

    # If an environment variable is specified, use that for the command
    if env:
        output = check_output(call, shell=True, env=env)

    # Return the output of the command
    return output.decode().strip()
