        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Validate root object
        if not hasattr(self, "root_object"):
            raise ValueError("Root object not found")

        if validate_objects:
            if not isinstance(self.root_object, AbstractElement):
                raise ValueError("Root object must be an instance of AbstractElement")

            if check_digests:
                if self.root_object.digest is None or self.root_object.digest == "":
                    raise ValueError("Root object digest not present")

                if self.root_object.digest != self.root_object.calculate_digest():
                    raise ValueError("Root object digest does not match calculated value")

        num_objects += 1
        good_objects += 1

        # Validate child objects
