                    if child.digest is None or child.digest == "":
                        raise ValueError("Child object digest not present")

                    if child.digest != child.calculate_digest():
                        raise ValueError("Child object digest does not match calculated value")

            num_objects += 1
            good_objects += 1

        # Check for duplicate ids
        if show_warnings and not self.root_object.check_duplicate_ids():
            warnings.warn("Duplicate ids found in hierarchy")

        return num_objects, good_objects

