def _replace_url_args(url, url_args):
    import re

    pattern = re.compile(r"\$(\w+)")  # pattern to match any custom string URL items
    matches = pattern.finditer(url)

    for match in matches:
        var_name = match.group(1)
        if var_name in url_args:
            url = url.replace(match.group(0), url_args[var_name])
        else:
            raise ValueError(f"URL argument '{var_name}' was not provided")

    return url

