    parse_errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config_data = json.load(f)
        except FileNotFoundError as e:
            logging.warning("Configuration file {} not found: {}".format(config_filename, e))
            continue
        except json.JSONDecodeError as e:
            logging.warning("Configuration file {} is not valid JSON: {}".format(config_filename, e))
            continue
        try:
            validate_config(config_data, overrides, resolve_env)
            parsed_configs[config_filename] = config_data
        except ValidationError as e:
            logging.warning("Configuration file {} failed validation: {}".format(config_filename, e))
            parse_errors.append(logging.LogRecord(logging.WARNING, "Configuration file {} failed validation: {}".format(config_filename, e)))
    return parsed_configs, parse_errors

