import re

class Bookmarks:
    def __init__(self, bookmarks):
        self.bookmarks = bookmarks

    @classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """

        bookmarks = []
        for value in values:
            bookmarks.append(cls.parse_raw_value(value))

        return cls(bookmarks)

    @staticmethod
    def parse_raw_value(value):
        """Parse a single ASCII string bookmark value into a Bookmark object.

        :param value: ASCII string value (raw bookmark)
        :type value: str
        :return: Bookmark object
        :rtype: Bookmark
        """

        m = re.match(r"Bookmark\(title=\"(?P<title>.*?)\", url=\"(?P<url>.*?)\"\)", value)
        if not m:
            raise ValueError('Invalid raw bookmark value')

        title = m.group('title')
        url = m.group('url')
        return Bookmark(title, url)

class Bookmark:
    def __init__(self, title, url):
        self.title = title
        self.url = url

    def repr__(self):
        return f"Bookmark(title='{self.title}', url='{self.url}')"
