def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    code_block = False

    for c in text:
        if code_block and c == '`':
            code_block = False
        elif c == '`':
            code_block = True
        elif code_block or c not in ['[',':']:
            continue
        elif c == '[':
            tag = get_tag(text)
            if tag:
                if replacer:
                    text = text.replace(tag, replacer(tag))
                tags.add(tag)
    return tags, text

def get_tag(text: str) -> str:
    """Get tag from text before next occurrence of ':', ignoring any presented matches in square brackets.

    Returns the tag or '' if none found.
    """
    match = re.search(r"\[[a-zA-Z]+\]|\s?[a-zA-Z]+\s?:\s?[a-zA-Z\s-]+[a-zA-Z\s-]+", text)
    return match[0].replace('`','').strip() if match else ''

