def validate_from_content(cls, spec_content=None):
    """Validate that spec (YAML) content has all required fields.

    This method check if spec (YAML) content has all required fields.

    Args:
        cls: The class of the element to validate.
        spec_content (str): The content of the spec file.

    Returns:
        Dictionary with data loaded from a spec (YAML) file.

    Raises:
        IRValidatorException: When mandatory data is missing in spec file.
    """
    if not spec_content:
        raise ValueError("Spec content is missing")

    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

    # Check if mandatory keys are present
    for key in cls.REQUIRED_KEYS:
        if key not in spec_data:
            raise IRValidatorException(f"Mandatory key '{key}' is missing in spec file")

    # Check if all required values are not None
    for key, value in spec_data.items():
        if key in cls.REQUIRED_KEYS and value is None:
            raise IRValidatorException(f"Value '{value}' in '{key}' is not defined")

    return spec_data

