@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise ValueError("Spec content cannot be empty")

    try:
        data = yaml.load(spec_content, Loader=yaml.FullLoader)
    except yaml.YAMLError as exc:
        raise IRValidatorException("Invalid spec content: " + str(exc))

    mandatory_keys = ["root_block", "optional_data"]

    # check that all mandatory keys are present
    for key in mandatory_keys:
        if key not in data:
            raise IRValidatorException("Missing mandatory key '" + key + "' in spec content")

    # check that root_block is valid
    if "type" not in data["root_block"]:
        raise IRValidatorException("Missing mandatory key 'type' in root_block")

    root_block_type = data["root_block"]["type"]
    if root_block_type not in ALLOWED_ROOT_BLOCK_TYPES:
        raise IRValidatorException("Invalid root block type '" + root_block_type + "'")

    # check that optional_data is a dictionary
    if not isinstance(data["optional_data"], dict):
        raise IRValidatorException("optional_data must be a dictionary")

    return data

